#ifndef ATLAB_DEBUG_LOG_H
#define ATLAB_DEBUG_LOG_H

#include <stdint.h>

/* If USB Device CDC stack was generated by CubeMX, define
 * ATLAB_USE_USB_CDC for the compiler and call MX_USB_DEVICE_Init()
 * before ATLAB_Demo_Run(). Otherwise the latest log is kept for
 * debugger inspection only; no physical USB print is claimed.
 */
extern volatile uint32_t atlab_log_calls;
extern volatile uint32_t atlab_log_drops;
extern char atlab_last_log[128];

void ATLAB_Log(const char *format, ...);

#endif
